CREATE TABLE IF NOT EXISTS schema_migrations(name text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY,owner_id text NOT NULL,revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft',document jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX IF NOT EXISTS projects_owner ON projects(owner_id,updated_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS assets(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id text NOT NULL,storage_key text NOT NULL UNIQUE,metadata jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id text NOT NULL,revision integer NOT NULL,kind text NOT NULL CHECK(kind IN ('sample','render','voice')),shot_id uuid,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','cancelled')),progress integer NOT NULL DEFAULT 0,stage text NOT NULL DEFAULT '等待执行',snapshot jsonb NOT NULL,idempotency_key text NOT NULL UNIQUE,attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,worker_id text,error text,retryable boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status,created_at);
CREATE TABLE IF NOT EXISTS artifacts(id uuid PRIMARY KEY,job_id uuid NOT NULL UNIQUE REFERENCES jobs(id),project_id uuid NOT NULL REFERENCES projects(id),owner_id text NOT NULL,revision integer NOT NULL,kind text NOT NULL,storage_key text NOT NULL UNIQUE,width integer NOT NULL DEFAULT 0,height integer NOT NULL DEFAULT 0,duration double precision NOT NULL DEFAULT 0,sha256 text NOT NULL,checks jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(project_id uuid NOT NULL REFERENCES projects(id),revision integer NOT NULL,owner_id text NOT NULL,artifact_id uuid NOT NULL REFERENCES artifacts(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS usage_events(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),job_id uuid REFERENCES jobs(id),owner_id text NOT NULL,provider text NOT NULL,operation text NOT NULL,request_id text,units jsonb NOT NULL,cost numeric,currency text NOT NULL DEFAULT 'CNY',created_at timestamptz NOT NULL DEFAULT now());
